import 'package:flutter/material.dart';import 'package:flutter/services.dart';import 'package:zan/Core/Resources/app_colors.dart';import '../../../Config/Routes/route_constants.dart';import '../../../main.dart';import 'Loading.dart';import 'background_painter.dart';import 'build_main_details_splash.dart';class SplashBody extends StatefulWidget {  const SplashBody({super.key});  @override  State<SplashBody> createState() => _SplashBodyState();}class _SplashBodyState extends State<SplashBody>    with SingleTickerProviderStateMixin {  late AnimationController _controller;  late Animation<double> _fadeAnimation;  @override  void initState() {    super.initState();    SystemChrome.setEnabledSystemUIMode(SystemUiMode.immersiveSticky);    _controller = AnimationController(      vsync: this,      duration: const Duration(seconds: 5), // Animation duration    );    _fadeAnimation = Tween<double>(begin: 0.0, end: 1.0).animate(      CurvedAnimation(parent: _controller, curve: Curves.easeIn),    );    _controller.forward();    // _controller.addListener(() {++++    //    //   if (_controller.isCompleted) {    //     Duration(seconds: 5);    //     _navigateToNextScreen();    //   }    // });    _controller.addStatusListener((status) {      if (status == AnimationStatus.completed) {        _navigateToNextScreen(); // Navigate after animation completes      }    });  }  void _navigateToNextScreen() async {    // Todo:: Hive (store true when user logged in first time)    await navigationService.clearAndNavigateTo(RouteNames.start);  }  @override  void dispose() {    _controller.dispose();    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);    super.dispose();  }  @override  Widget build(BuildContext context) {    return Scaffold(      backgroundColor: AppColors.primaryColor,      body: Stack(        children: [          Positioned.fill(            child: CustomPaint(              painter: BackgroundPainter(),              size: Size.infinite,            ),          ),          LogoAndText(            fadeAnimation: _fadeAnimation,            time: _controller.value,          ),          _controller.value < 0.05 ? Container() : Loading(),        ],      ),    );  }}